use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input_array = input.as_array().unwrap();
    let mut total = 0;

    for item in input_array {
        let item_array = item.as_array().unwrap();
        let unit_price = item_array[0].as_i64().unwrap();
        let quantity = item_array[1].as_i64().unwrap();
        total += unit_price * quantity;
    }

    json!(total)
}
